package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

public class AuditClaimAdded {
    public void audit(@Val Claim claim, @Val Person person,
            @RequestHeader(value = "X-User", required = false) String user, Audit audit) {
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record(Audit.line("CLAIM_ADDED", claim.sheetId(), user, "person=" + person.name(),
                "amount=" + shown.amount(), "date=" + shown.date()));
    }
}
EOF
cat > claim/AuditClaimEdited.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

public class AuditClaimEdited {
    // The loaded claim names the sheet and person; the edited one (as the screen sees it) the values.
    public void audit(@Val Claim loaded, @Val ClaimResponse edited, People people,
            @RequestHeader(value = "X-User", required = false) String user, Audit audit) {
        Person person = people.find(loaded.sheetId(), loaded.personId());
        audit.record(Audit.line("CLAIM_EDITED", loaded.sheetId(), user,
                "person=" + (person == null ? "" : person.name()), "amount=" + edited.amount(),
                "date=" + edited.date()));
    }
}
EOF
